class Solution {
public:
    int shortestPath(std::vector<std::vector<int>>& grid, int k) {
        int m = grid.size(), n = grid[0].size();
        if (k >= m + n - 2) return m + n - 2;
        std::vector<std::vector<int>> maxRem(m, std::vector<int>(n, -1));
        std::queue<std::vector<int>> q;
        q.push({0, 0, k, 0});
        maxRem[0][0] = k;
        int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!q.empty()) {
            auto cur = q.front();
            q.pop();
            int r = cur[0], c = cur[1], rem = cur[2], steps = cur[3];
            if (r == m - 1 && c == n - 1) return steps;
            for (auto& d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                    int nrem = rem - grid[nr][nc];
                    if (nrem >= 0 && maxRem[nr][nc] < nrem) {
                        maxRem[nr][nc] = nrem;
                        q.push({nr, nc, nrem, steps + 1});
                    }
                }
            }
        }
        return -1;
    }
};

import java.util.*;

class Solution {
    public int shortestPath(int[][] grid, int k) {
        int m = grid.length, n = grid[0].length;
        if (k >= m + n - 2) return m + n - 2;
        int[][] maxRem = new int[m][n];
        for (int[] row : maxRem) Arrays.fill(row, -1);
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{0, 0, k, 0});
        maxRem[0][0] = k;
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1], rem = cur[2], steps = cur[3];
            if (r == m - 1 && c == n - 1) return steps;
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                    int nrem = rem - grid[nr][nc];
                    if (nrem >= 0 && maxRem[nr][nc] < nrem) {
                        maxRem[nr][nc] = nrem;
                        q.offer(new int[]{nr, nc, nrem, steps + 1});
                    }
                }
            }
        }
        return -1;
    }
}

var shortestPath = function(grid, k) {
    const m = grid.length, n = grid[0].length;
    if (k >= m + n - 2) return m + n - 2;
    const maxRem = Array.from({ length: m }, () => new Int32Array(n).fill(-1));
    const q = [[0, 0, k, 0]];
    maxRem[0][0] = k;
    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    let head = 0;
    while (head < q.length) {
        const [r, c, rem, steps] = q[head++];
        if (r === m - 1 && c === n - 1) return steps;
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                const nrem = rem - grid[nr][nc];
                if (nrem >= 0 && maxRem[nr][nc] < nrem) {
                    maxRem[nr][nc] = nrem;
                    q.push([nr, nc, nrem, steps + 1]);
                }
            }
        }
    }
    return -1;
};
